function SumProperDivisors(n)
    s := 1;
    for i := 2 to Isqrt(n) do
        if n mod i eq 0 then
            s +:= i;
            if i ne n div i then
                s +:= n div i;
            end if;
        end if;
    end for;
    if n eq 1 then return 0; end if;
    return s;
end function;

